package com.cloudcart.security;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import java.util.List;
@Configuration public class SecurityConfig {@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}@Bean SecurityFilterChain chain(HttpSecurity http,JwtFilter filter)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/error").permitAll().requestMatchers(HttpMethod.GET,"/api/products/**").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers(HttpMethod.POST,"/api/products/**").hasRole("ADMIN").requestMatchers(HttpMethod.PUT,"/api/products/**").hasRole("ADMIN").requestMatchers(HttpMethod.DELETE,"/api/products/**").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}@Bean org.springframework.web.cors.CorsConfigurationSource cors(@Value("${app.cors-origin}")String origin){var c=new org.springframework.web.cors.CorsConfiguration();c.setAllowedOrigins(List.of(origin));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("*"));c.setAllowCredentials(true);var s=new org.springframework.web.cors.UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}}
